END
GO

/* =====================================================================================
   BƯỚC 2: CHUẨN HÓA STORED PROCEDURE ĐIỀU PHỐI [dbo].[sp_Sub_SubQuotation]
   ===================================================================================== */
CREATE OR ALTER PROCEDURE [dbo].[sp_Sub_SubQuotation](
    @LoginID INT = NULL,
    @LanguageID VARCHAR(5) = 'VN'
)
AS
BEGIN
    SET NOCOUNT ON;
    IF @LanguageID IS NULL OR LTRIM(RTRIM(@LanguageID)) = ''
        SET @LanguageID = 'VN';
    SELECT TOP 1 html
    FROM tblHtmlScriptCache
    WHERE TableName = 'sp_Sub_SubQuotation'
      AND ScreenType = -1
      AND LanguageID = @LanguageID;
END
GO

/* =====================================================================================
   BƯỚC 3: BIÊN DỊCH MÃ NGUỒN GIAO DIỆN VÀO BẢNG CACHE VÀ ĐỒNG BỘ CẢ 2 NGÔN NGỮ (VN & EN)
   ===================================================================================== */
IF OBJECT_ID('dbo.sp_GenerateHTMLScript_new', 'P') IS NOT NULL
BEGIN
    EXEC sp_GenerateHTMLScript_new 'sp_Sub_SubQuotation_html', 'VN', 'sp_Sub_SubQuotation';
    EXEC sp_GenerateHTMLScript_new 'sp_Sub_SubQuotation_html', 'EN', 'sp_Sub_SubQuotation';
END
ELSE
BEGIN
    EXEC sp_GenerateHTMLScript 'sp_Sub_SubQuotation_html';
END
GO


