            gap: 8px;
        }

        #customerKanbanComponent .col-loading-skeleton-card .skeleton-line:nth-child(1) {
            width: 72%;
        }

        #customerKanbanComponent .col-loading-skeleton-card .skeleton-line:nth-child(2) {
            width: 56%;
        }

        #customerKanbanComponent .col-loading-skeleton-card .skeleton-line:nth-child(3) {
            width: 84%;
        }

        @keyframes kanbanSkeletonShimmer {
            0% {
                background-position: 200% 0;
            }

            100% {
                background-position: -200% 0;
            }
        }

        #customerKanbanComponent .empty-state {
            text-align: center;
            padding: 40px 20px;

        }


        #customerKanbanComponent .empty-state i {
            font-size: 48px;
            margin-bottom: 5px;
            opacity: 0.5;
        }

        /* Scrollbar styling */
        #customerKanbanComponent .kanban-board::-webkit-scrollbar {
            height: 8px;
        }

        #customerKanbanComponent .kanban-board::-webkit-scrollbar-track {
            background: rgba(0, 0, 0, 0.05);
            border-radius: 4px;
        }

        #customerKanbanComponent .kanban-board::-webkit-scrollbar-thumb {
            background: #198754;
            border-radius: 4px;
        }

        /* Responsive Design */
        /* BẢO TOÀN KÍCH THƯỚC CỘT KANBAN: flex-shrink: 0, min-width: 220px (Zero Internal Mutation) */
        @media (max-width: 1200px) {
            #customerKanbanComponent .kanban-column {
                flex: 0 0 220px;
                min-width: 220px;
            }
        }

        /* WINDOWS SNAP 1/2 (~960px - 1024px): Giữ nguyên bố cục phẳng, không ép column */
        @media (max-width: 992px) {
            #customerKanbanComponent {
                padding: 15px;
            }

            #customerKanbanComponent .kanban-column {
                flex: 0 0 220px;
                min-width: 220px;
            }

            #customerKanbanComponent .kanban-header {
                gap: 12px;
            }

            #customerKanbanComponent .toolbar-right-actions {
                margin-left: auto !important;
            }
        }

        /* TABLET & SNAP 1/3 (768px): Cụm Right Actions bám sát lề phải, Date Input co giãn */
        @media (max-width: 768px) {
            #customerKanbanComponent {
                padding: 10px;
            }

            #customerKanbanComponent .kanban-column {
                flex: 0 0 220px;
                min-width: 220px;
            }

            #customerKanbanComponent .date-input-group {
                flex: 0 0 auto;
            }

            #customerKanbanComponent .toolbar-right-actions {
                width: 100%;
                justify-content: flex-end;
                margin-left: auto !important;
            }

            #customerKanbanComponent .search-box-wrapper {
                flex: 1 1 auto;
                min-width: 200px;
                max-width: 320px;
            }
        }

        /* MOBILE (<= 576px): Wrap nhẹ nhàng khi hết chỗ, giữ nguyên 100% style của Card */
        @media (max-width: 576px) {
            #customerKanbanComponent {
                padding: 8px;
            }

            #customerKanbanComponent .kanban-column {
                flex: 0 0 220px;
                min-width: 220px;
            }

            #customerKanbanComponent .toolbar-right-actions {
                flex-wrap: wrap;
                width: 100%;
                gap: 8px;
                justify-content: flex-start;
            }

            #customerKanbanComponent .search-box-wrapper {
                width: 100%;
                min-width: 100%;
                max-width: 100%;
            }
        }
   </style>
