            align-items: center;
            gap: 8px;
            transition: all 0.3s ease;
        }

        .dc-filter .btn-filter {
            background-color: #198754;
            color: white;
        }

        .dc-filter .btn-filter:hover {
            background-color: #157347;
            transform: translateY(-2px);
            box-shadow: 0 4px 12px rgba(25, 135, 84, 0.4);
        }

