        /* Loading overlay styles */
        .ai-processing-overlay {
            position: fixed;
            top: 0;
            left: 0;
            width: 100%;
            height: 100%;
            background: rgba(0, 0, 0, 0.7);
            display: none;
            justify-content: center;
            align-items: center;
            z-index: 9999;
            flex-direction: column;
        }

        .ai-processing-overlay.show {
            display: flex !important;
        }

        .ai-spinner {
            width: 60px;
            height: 60px;
            border: 4px solid #e9ecef;
            border-top: 4px solid #198754;
            border-radius: 50%;
            animation: ai-spin 1s linear infinite;
            margin-bottom: 20px;
        }

        @keyframes ai-spin {
            0% {
                transform: rotate(0deg);
            }

            100% {
                transform: rotate(360deg);
            }
        }

        .ai-processing-text {
            color: white;
            font-size: 16px;
            font-weight: 500;
            text-align: center;
            margin-bottom: 10px;
        }

        .ai-processing-subtext {
            color: #ccc;
            font-size: 14px;
            text-align: center;
        }

        .modal-content.processing {
            opacity: 0.6;
            pointer-events: none;
        }

        .image-processing-indicator {
            position: absolute;
            top: 50%;
            left: 50%;
            transform: translate(-50%, -50%);
            background: rgba(25, 135, 84, 0.9);
            color: white;
            padding: 15px 25px;
            border-radius: 8px;
            display: none;
            flex-direction: column;
            align-items: center;
            gap: 10px;
            z-index: 1000;
        }

        .image-processing-indicator.show {
            display: flex !important;
        }

        .mini-spinner {
            width: 24px;
            height: 24px;
            border: 3px solid rgba(255, 255, 255, 0.3);
            border-top: 3px solid white;
            border-radius: 50%;
