            function setSelectBoxValue(instance, dataSource, value) {
                // Kiểm tra instance có tồn tại không
                if (!instance) {
                    console.error("Instance không tồn tại");
                    return false;
                }

                // Kiểm tra dataSource có data không
                if (!dataSource || (Array.isArray(dataSource) && dataSource.length === 0)) {
                    console.warn("DataSource trống hoặc không tồn tại");
                    return false;
                }

                // Nếu dataSource là array
                if (Array.isArray(dataSource)) {
                    instance.option("dataSource", dataSource);
'
+ N'                    // Đợi render xong rồi set value
                    setTimeout(function () {
                        instance.option("value", value);
                    }, 50);
                    return true;
                }

                // Nếu dataSource là DataSource object hoặc promise
                if (dataSource.load && typeof dataSource.load === ''function'') {
                    dataSource.load().done(function (items) {
                        if (items && items.length > 0) {
                            instance.option("dataSource", items);
                            setTimeout(function () {
                                instance.option("value", value);
                            }, 50);
                        } else {
                            console.warn("DataSource load nhung không có items");
                        }
                    }).fail(function (error) {
        console.error("Lỗi khi load dataSource:", error);
                    });
                    return true;
                }

                // Trường hợp dataSource là object config
                instance.option("dataSource", dataSource);
                setTimeout(function () {
                    instance.option("value", value);
                }, 50);

                return true;
            }
