            // Upload file function
            async function UploadMergeFileSplit(src, fileName) {
                let splitImage = src.match(/.{1,500000}/g)
                let totalIndex = splitImage.length
                let index = 0
                let tempName = uuidv4() + ".tmp"
                if (!fileName) fileName = tempName
                let pathResult = ""

                while (index < totalIndex) {
                    try {
                        data = await AjaxHPAParadiseParadiseAsync({
                            data: {
                                sendEncryption: false,

                                name: "MergeFileSplit",
                                param: [
'
+ N'                                    splitImage[index],
                                    index,
                                    totalIndex,
                                    tempName,
                                    fileName,
                                ]
                            },
                        })
                        index += 1;
                        pathResult = data;
                    } catch (error) {
                        if (error.status == 200) index += 1;
                    }
                }
                return pathResult;
            }

            // Generate UUID for temp file names
            function uuidv4() {
                return ''xxxxxxxx-xxxx-4xxx-yxxx-xxxxxxxxxxxx''.replace(/[xy]/g, function (c) {
                    var r = Math.random() * 16 | 0, v = c == ''x'' ? r : (r & 0x3 | 0x8);
                    return v.toString(16);
                });
            }

            // Validate image mime type
            function isValidImageType(file) {
                const validTypes = [
                    ''image/jpeg'',
                    ''image/png'',
                    ''image/webp'',

                    ''image/gif'',
                    ''image/heic''
                ];
                return validTypes.includes(file.type);
            }

            // Get file extension from mime type
            function getFileExtension(mimeType) {
                const mimeMap = {
'
+ N'                    ''image/jpeg'': ''.jpg'',
                    ''image/png'': ''.png'',
                    ''image/webp'': ''.webp'',
                    ''image/gif'': ''.gif'',
                    ''image/heic'': ''.heic''
                };
                return mimeMap[mimeType] || ''.jpg'';
            }

