        #sp_CRM_SaleInCRM_Premium .badge-ttv-due { background: var(--paradise-bg-warning-subtle); color: var(--paradise-color-warning); border: 1px solid var(--paradise-bg-warning-subtle); }
        #sp_CRM_SaleInCRM_Premium .badge-ttv-paid { background: var(--paradise-bg-success-subtle); color: var(--paradise-color-success); border: 1px solid var(--paradise-bg-success-subtle); }
