        frame.srcdoc = fullContent;
           $(''#Outlook_emailPopup'').addClass(''show'');
                    }
                },
 error: function (error) {
                    console.error(''Error loading email:'', error);
              alert(''Không thể tải email. Vui lòng thử lại.'');
                }
