          ? window.LanguageID
          : typeof LanguageID !== "undefined"
            ? LanguageID
            : null;

      const snapshotGridData = function (instance) {
        if (!instance) return [];
        try {
          // Ưu tiên đọc raw dataSource trước - luôn có FULL data
          // kể cả khi toolbar search/filter đang active
          if (typeof instance.option === "function") {
            const rawData = instance.option("dataSource");
            if (Array.isArray(rawData) && rawData.length > 0) {
              return rawData.map(function (item) {
                return item && typeof item === "object"
                  ? Object.assign({}, item)
                  : item;
              });
            }
          }

          // Fallback: ds.items() - CHÚ Ý: chỉ trả về filtered rows
          if (typeof instance.getDataSource === "function") {
            const ds = instance.getDataSource();
            if (ds && typeof ds.items === "function") {
              const dsItems = ds.items();
              if (Array.isArray(dsItems) && dsItems.length > 0) {
                return dsItems.map(function (item) {
                  return item && typeof item === "object"
                    ? Object.assign({}, item)
                    : item;
                });
              }
            }
          }
        } catch (snapshotErr) {
          console.warn(
            "[SharedGrid] Unable to snapshot grid data",
            snapshotErr,
          );
        }
        return [];
      };

      let sharedEntry = window.hpaSharedGridDataSources[sharedKey];
      if (!sharedEntry) {
        sharedEntry = {
          data: [],

          subscribers: [],
          loading: false,
        };
      }

      sharedEntry.primaryKey = sharedEntry.primaryKey || primaryKeyField;
      sharedEntry.data = Array.isArray(sharedEntry.data)
        ? sharedEntry.data
        : [];
      sharedEntry.subscribers = Array.isArray(sharedEntry.subscribers)
        ? sharedEntry.subscribers
        : [];

      sharedEntry.loading = !!sharedEntry.loading;

      if (typeof sharedEntry.normalizeParams !== "function") {
        sharedEntry.normalizeParams = function (customParams) {
          const base = [];
          if (loginValue !== null && loginValue !== undefined) {
            base.push("LoginID", loginValue);
          }
          if (languageValue !== null && languageValue !== undefined) {
            base.push("LanguageID", languageValue);
          }

          if (Array.isArray(customParams) && customParams.length > 0) {
            return base.concat(customParams);
          }

          if (customParams && typeof customParams === "object") {
            const extras = [];
            Object.keys(customParams).forEach(function (key) {
              extras.push(key, customParams[key]);
            });
            return base.concat(extras);
          }

          return base;
        };
      }

      if (typeof sharedEntry.notify !== "function") {
        sharedEntry.notify = function () {
          this.subscribers.forEach(function (callback) {
            try {
              callback(this.data);
            } catch (err) {
              console.error("[SharedGrid] subscriber error", err);
            }
          }, this);
        };
      }

      if (typeof sharedEntry.subscribe !== "function") {
        sharedEntry.subscribe = function (callback) {
          if (typeof callback === "function") {
            this.subscribers.push(callback);
          }
          return () => {
            this.subscribers = this.subscribers.filter(function (fn) {
              return fn !== callback;
            });
          };
        };
      }

      if (typeof sharedEntry.applyRowChanges !== "function") {
        sharedEntry.applyRowChanges = function (rowData, options) {
          const opts = options || {};
          const keyField = this.primaryKey;
          let keyValue = opts.key;
          if (
            (keyValue === undefined || keyValue === null) &&
            rowData &&
            rowData[keyField] !== undefined
          ) {
            keyValue = rowData[keyField];
          }

          if (keyValue === undefined || keyValue === null) {
            console.warn(
              "[SharedGrid] Missing key when applying row changes for",
              sharedKey,
            );
            return Promise.resolve(false);
          }

          if (typeof this.ensureLocalData === "function") {
            this.ensureLocalData();
          }

          const compare =
            opts.strict === true
              ? function (candidate) {
                  return candidate === keyValue;
                }
              : function (candidate) {
                  if (candidate === undefined || candidate === null)
                    return candidate === keyValue;
                  if (keyValue === undefined || keyValue === null) return false;
                  return String(candidate) === String(keyValue);
                };

          const nextData = Array.isArray(this.data) ? this.data.slice() : [];
          let targetIndex = nextData.findIndex(function (item) {
            return item ? compare(item[keyField]) : false;
          });

          const normalizedRow = Object.assign(
            {},
            targetIndex > -1 ? nextData[targetIndex] : {},
            rowData,
          );

          if (targetIndex === -1) {
            if (opts.ignoreMissing === true) {
              return Promise.resolve(false);
            }
   if (opts.append === true) {
              nextData.push(normalizedRow);
              targetIndex = nextData.length - 1;
            } else {
              nextData.unshift(normalizedRow);
              targetIndex = 0;
            }
          } else {
            nextData[targetIndex] = normalizedRow;
          }

          this.data = nextData;
          try {
            if (this.instance && typeof this.instance.option === "function") {
              this.instance.option("dataSource", nextData);
              this.instance.refresh();
            }
          } catch (applyErr) {
            console.warn("[SharedGrid] Unable to push row update", applyErr);
          }
          this.notify();
          return Promise.resolve({ index: targetIndex, data: normalizedRow });
        };
      }

      if (typeof sharedEntry.removeRow !== "function") {
        sharedEntry.removeRow = function (options) {
          const opts = options || {};
          const keyField = this.primaryKey;
          const keyValue = opts.key;

          if (keyValue === undefined || keyValue === null) {
            console.warn(
              "[SharedGrid] Missing key when removing row for",
              sharedKey,
            );
            return Promise.resolve(false);
          }

          if (typeof this.ensureLocalData === "function") {
            this.ensureLocalData();
          }

          const filtered = (Array.isArray(this.data) ? this.data : []).filter(
            function (item) {
              if (!item) return true;
              const candidate = item[keyField];
              if (opts.strict === true) {
                return candidate !== keyValue;
              }

              if (candidate === undefined || candidate === null) {
                return keyValue !== candidate;
              }
              return String(candidate) !== String(keyValue);
            },
          );

          if (
            filtered.length ===
            (Array.isArray(this.data) ? this.data.length : 0)
          ) {
            return Promise.resolve(false);
          }

          this.data = filtered;
          try {
            if (this.instance && typeof this.instance.option === "function") {
              this.instance.option("dataSource", filtered);
              this.instance.refresh();
            }
          } catch (removeErr) {
            console.warn("[SharedGrid] Unable to remove row", removeErr);
          }
          this.notify();
          return Promise.resolve(true);
        };
      }

      sharedEntry.instance =
        InstancegridSubProductListP8F9FB1B1CC3A4599BCFD3BE6C5D75A53;

      if (typeof sharedEntry.ensureLocalData !== "function") {
        sharedEntry.ensureLocalData = function () {
          if (Array.isArray(this.data) && this.data.length > 0) {
            return;
          }
          const snapshot = snapshotGridData(this.instance);
          if (snapshot.length > 0) {
            this.data = snapshot;
          }
        };
      }

      const currentSnapshot = snapshotGridData(sharedEntry.instance);
      if (currentSnapshot.length > 0) {
        sharedEntry.data = currentSnapshot;
      }

      sharedEntry.getData = function () {
        return this.data;
      };

      // Gọi sau khi API reload data mới để sync lại cache
      sharedEntry.syncFromGrid = function () {
        const fresh = snapshotGridData(this.instance);
        if (fresh.length > 0) {
          this.data = fresh;
        }
        return this.data;
      };

      window.hpaSharedGridDataSources[sharedKey] = sharedEntry;
    })();

    window.currentRecordID_SubID = null;

    function clearPageCache() {
      _pageCache = {};
    }

    function getGridHeight() {
      const gridEl =
        InstancegridSubProductListP8F9FB1B1CC3A4599BCFD3BE6C5D75A53.element();
      const domElement = gridEl.jquery ? gridEl[0] : gridEl;
      const top = domElement.getBoundingClientRect().top;
      return window.innerHeight - top - 20;
    }

    function ReloadData(pageNumber, pageSize, keyword = null) {
      _pageCache = {};

      let _currentKeyword = String(
        keyword != null
          ? keyword
          : InstancegridSubProductListP8F9FB1B1CC3A4599BCFD3BE6C5D75A53.option(
              "searchPanel.text",
            ) || "",
      ).trim();

      function _applyRecord(results) {
        window.syncSharedGridData("gridSubProductList");
      }

      dataStore_gridSubProductList = new DevExpress.data.CustomStore({
        key: "SubID",
        load: function (loadOptions) {
          const deferred = $.Deferred();

          if (!api) {
            const results = DataSource || [];
            const skip = loadOptions.skip || 0;
            const take = loadOptions.take || 50;
            const pageData = results.slice(skip, skip + take);
            deferred.resolve({
              data: pageData,
              totalCount: results.length,
            });
            api = true;
            return deferred.promise();
          }

          let params = [];

          // SP nghiệp vụ
          params.push("@ProcName", "sp_Sub_SubProduct_Get");

          // Tham số của tên thủ tục load Data
          let procParam = "";
          // @LoginID = window.UserID, @LanguageID = window.LanguageID,......

          params.push("@ProcParam", procParam);

          // Phân trang
          params.push("@Take", loadOptions.take || 50);
          params.push("@Skip", loadOptions.skip || 0);

          // TotalCount
          if (loadOptions.requireTotalCount) {
            params.push("@RequireTotalCount", 1);
          }

          // Sort
          const sort = loadOptions.sort
            ? loadOptions.sort
                .map((s) => s.selector + (s.desc ? " DESC" : " ASC"))
                .join(",")
            : "SubID ASC"; // này cho mặc định. tự chỉnh theo menu mỗi người

          params.push("@Sort", "ORDER BY " + sort);

          // Search
          if (_currentKeyword) {
            params.push("@SearchValue", _currentKeyword);
            params.push("@ColumnSearch", "");
            // tên cột muốn search, không dc để trống nếu có search
          }

          // Filter
          if (loadOptions.filter) {
            // Kiểm tra filter item có phải function không
            const isJSFunction = (item) => typeof item === "function";

            const hasFunction = JSON.stringify(
              loadOptions.filter,
              (key, val) => {
                if (typeof val === "function") return "FUNCTION";
                return val;
              },
            ).includes("FUNCTION");

            if (!hasFunction) {
              params.push("@Filters", createConditionQuery(loadOptions.filter));
            }
          }
          // Filter
          // if (loadOptions.filter) {
          //     params.push("@Filters", createConditionQuery(loadOptions.filter));
          // }

          // Group
          if (loadOptions.group) {
            let selectGroup = "",
              groupBy = "GROUP BY ";
            loadOptions.group.forEach((item, index) => {
              if (selectGroup) selectGroup += ", ";
              if (groupBy !== "GROUP BY ") groupBy += ", ";
              if (item.groupInterval) {
                selectGroup += `${item.groupInterval.toUpperCase()}(${item.selector}) as col${index}`;
                groupBy += `${item.groupInterval.toUpperCase()}(${item.selector})`;
              } else {
                selectGroup += `${item.selector} as col${index}`;
                groupBy += `${item.selector}`;
              }
            });
            selectGroup += `, Count(*) as totalCount`;
            params.push("@SelectGroup", selectGroup);
            params.push("@GroupBy", groupBy);
   }

          // Summary
          if (loadOptions.totalSummary) {
            const summary = loadOptions.totalSummary.map((item) => {
              const type =
                item.summaryType === "custom"
                  ? `count(CASE WHEN [${item.selector}] = 1 THEN 1 END) as ${item.selector}_COUNT`
                  : `${item.summaryType}([${item.selector}]) as ${item.selector}_${item.summaryType.toUpperCase()}`;
              return type;
            });
            params.push("@TotalSummary", summary.join(", "));
          }

          AjaxHPAParadise({
            data: {
              name: "sp_LoadGridUsingAPI",
              param: params,
            },
            success: function (res) {
              const json = typeof res === "string" ? JSON.parse(res) : res;
              const results = Array.isArray(json?.data?.[0])
                ? json.data[0]
                : [];

              let result = { data: results };

              if (loadOptions.requireTotalCount) {
                result.totalCount = json?.data?.[1]?.[0]?.TotalCount ?? 0;
                if (loadOptions.totalSummary) {
                  result.summary = Object.values(json?.data?.[2]?.[0] ?? {});
                }
              } else {
                if (loadOptions.totalSummary) {
                  result.summary = Object.values(json?.data?.[1]?.[0] ?? {});
                }
              }

              DataSource = results;
              _applyRecord(results);

              deferred.resolve(result);
            },
            error: function (err) {
              deferred.reject("Data Loading Error");
            },
          });

          return deferred.promise();
        },
      });

      const gridInstance =
        InstancegridSubProductListP8F9FB1B1CC3A4599BCFD3BE6C5D75A53;
      gridInstance.beginUpdate();
      gridInstance.option("remoteOperations", {
        paging: true,
        filtering: true,
        sorting: true,
        searching: true,
      });

      // scrolling mode, nếu phân trang bình thường thì bỏ scrolling
      gridInstance.option("scrolling.mode", "infinite");
      gridInstance.option("scrolling.rowRenderingMode", "virtual");
      gridInstance.option("scrolling.preloadEnabled", false);

      gridInstance.option("paging.enabled", true);
      gridInstance.option("paging.pageSize", 50);
      gridInstance.option("pager.visible", false); // bật cái này để hiện số trang, dùng cho list click vô số trang rồi mở trang đó.
      gridInstance.option("pager.allowedPageSizes", [50]);
      gridInstance.option("searchPanel.highlightSearchText", false);
      gridInstance.option("dataSource", dataStore_gridSubProductList);
      gridInstance.option("height", getGridHeight());
      gridInstance.option("onOptionChanged", function (e) {
        if (e.name === "searchPanel" && e.fullName === "searchPanel.text") {
          const raw = e.value || "";
          let t = String(raw);
          _currentKeyword = t.trim();
          _pageCache = {};
        }
      });
      gridInstance.endUpdate();
    }
  

    ReloadData();
  })();
</script>

 '
 SELECT @html as html
  -- exec sp_GenerateHTMLScript_new 'sp_Sub_SubProduct_html'

END

GO

/*-------------------------------------------------------------------
 BÆ¯á»šC 2: CHUáº¨N HÃ“A STORED PROCEDURE ÄIá»€U PHá»I [dbo].[sp_Sub_SubProduct]
--------------------------------------------------------------------*/
ALTER PROCEDURE [dbo].[sp_Sub_SubProduct](
    @LoginID INT = NULL,
    @LanguageID VARCHAR(5) = 'VN',
    @EmployeeID VARCHAR(20) = NULL
)
AS
BEGIN
    SET NOCOUNT ON;
    IF @LanguageID IS NULL OR LTRIM(RTRIM(@LanguageID)) = ''
        SET @LanguageID = 'VN';

    DECLARE @html NVARCHAR(MAX);
    SELECT TOP 1 @html = html
    FROM tblHtmlScriptCache
    WHERE (TableName = 'sp_Sub_SubProduct_html' OR TableName = 'sp_Sub_SubProduct')
      AND ScreenType = -1
      AND LanguageID = @LanguageID;

    IF @html IS NOT NULL
        SELECT @html AS html;
    ELSE
        SELECT TOP 1 html
        FROM tblHtmlScriptCache
        WHERE (TableName = 'sp_Sub_SubProduct_html' OR TableName = 'sp_Sub_SubProduct')
          AND ScreenType = -1;
END
GO

/*-------------------------------------------------------------------
 BÆ¯á»šC 3: BIÃŠN Dá»ŠCH MÃƒ NGUá»’N GIAO DIá»†N VÃ€O Báº¢NG CACHE VÃ€ Cáº¬P NHáº¬T VERSION
--------------------------------------------------------------------*/
IF OBJECT_ID('dbo.sp_GenerateHTMLScript_new', 'P') IS NOT NULL
BEGIN
    EXEC sp_GenerateHTMLScript_new 'sp_Sub_SubProduct_html', 'VN', 'sp_Sub_SubProduct';
    EXEC sp_GenerateHTMLScript_new 'sp_Sub_SubProduct_html', 'EN', 'sp_Sub_SubProduct';
    EXEC sp_GenerateHTMLScript_new 'sp_Sub_SubProduct_html', 'VN', 'sp_Sub_SubProduct_html';
    EXEC sp_GenerateHTMLScript_new 'sp_Sub_SubProduct_html', 'EN', 'sp_Sub_SubProduct_html';
END
ELSE
BEGIN
    EXEC sp_GenerateHTMLScript 'sp_Sub_SubProduct_html';
END
GO

-- ===================================================================
-- PATCH 17: [sp_WH_ProductList_html] & [sp_WH_ProductList]
-- MÀN HÌNH: Trang chủ CRM > Kho > Danh mục sản phẩm (MnuCRM_WH_ProductList)
-- MÔ TẢ: Chuẩn hóa Responsive theo Bộ 9 Quy tắc Bất biến (/responsive-rules)
--        1. Khóa cố định Searchbox 200px: Tuyệt đối không tự động giãn lấp đầy dòng
--        2. Bình đẳng hóa phần tử con (Flat Siblings): Từng button rớt hàng độc lập
--        3. Sửa lỗi chia 2 cột của bộ lọc tồn kho: Đưa về 3 cột đều nhau 100%
--        4. Triệt tiêu bẫy thẻ bọc trung gian $btnGroup (Quy tắc 6.4)
--        5. Triệt tiêu lỗi vỡ toàn trang (mất hết) do Identifier 'colName' has already been declared
--           khi cơ chế Stale-While-Revalidate re-inject script vào Window
-- ===================================================================


ALTER PROCEDURE [dbo].[sp_WH_ProductList_html]
as
    DECLARE @html nvarchar(max) = '', @Empty nvarchar(max) = ''

    select @html = N'
      <style>
  /* =====================================================================
     RESPONSIVE DESIGN SYSTEM: sp_WH_ProductList (Danh mục sản phẩm)
     Tuân thủ Bộ 9 Quy tắc Bất biến về Bố cục & Widget (/responsive-rules)
     - Quy tắc 1 & 8: Khóa biên khung nhìn & Viewport Boundary Lock
     - Quy tắc 6 & 6.4: Toolbar rớt hàng tự do, triệt tiêu bẫy thẻ bọc trung gian
     - Quy tắc 7: Khóa nguyên tử nhãn chữ & nút bấm (Atomic Non-shrink)
     - Sửa lỗi chia 2 cột bộ lọc tồn kho: Đưa về 3 cột đều nhau 100%
     - Sửa lỗi ô tìm kiếm chiếm 100% đẩy văng các nút Action ra ngoài mép
     - Quy tắc 9: Cô lập cuộn bảng DataGrid (Wide-Component Scroll Isolation)
     ===================================================================== */

  /* 1. KHUNG CHỨA TOÀN TRANG: Khóa biên chống vỡ trang */
  #sp_WH_ProductList_html {
    width: 100% !important;
    height: 100% !important;
    min-width: 0 !important;
    max-width: 100% !important;
    overflow-x: hidden !important;
    box-sizing: border-box !important;
  }

  #sp_WH_ProductList_html *,
  #sp_WH_ProductList_html *::before,
  #sp_WH_ProductList_html *::after {
    box-sizing: border-box !important;
  }

  #sp_WH_ProductList_html #gridProductList {
    width: 100% !important;
    max-width: 100% !important;
    min-width: 0 !important;
    overflow: hidden !important;
  }

  #sp_WH_ProductList_html #gridProductList .dx-datagrid {
    max-width: 100% !important;
    min-width: 0 !important;
  }

  /* 2. TOOLBAR CONTAINER: Tự do co giãn theo chiều cao thực tế (Quy tắc 6) */
  #sp_WH_ProductList_html #gridProductList .dx-toolbar,
  #sp_WH_ProductList_html #gridProductList .dx-toolbar-items-container {
    height: auto !important;
    min-height: 40px !important;
    overflow: visible !important;
    background: transparent !important;
  }

  #sp_WH_ProductList_html #gridProductList .dx-toolbar-items-container {
    display: flex !important;
    flex-direction: row !important;
    flex-wrap: wrap !important;
    align-items: center !important;
    justify-content: space-between !important;
    gap: 10px !important;
    width: 100% !important;
    max-width: 100% !important;
    padding: 6px 0 !important;
    box-sizing: border-box !important;
  }

  /* 3. ĐỒNG CẤP HÓA CÁC CỤM TOOLBAR (BEFORE & AFTER): position static & bám lề */
  #sp_WH_ProductList_html #gridProductList .dx-toolbar-before,
  #sp_WH_ProductList_html #gridProductList .dx-toolbar-center,
  #sp_WH_ProductList_html #gridProductList .dx-toolbar-after {
    position: static !important;
    display: flex !important;
    align-items: center !important;
    flex-wrap: wrap !important;
    gap: 8px !important;
    height: auto !important;
    max-width: 100% !important;
    min-width: 0 !important;
    overflow: visible !important;
    white-space: normal !important;
    padding: 0 !important;
  }

  #sp_WH_ProductList_html #gridProductList .dx-toolbar-before {
    flex: 0 0 auto !important;
    width: auto !important;
  }

  #sp_WH_ProductList_html #gridProductList .dx-toolbar-after {
    flex: 1 1 auto !important;
    justify-content: flex-end !important;
    margin-left: auto !important;
  }

  #sp_WH_ProductList_html #gridProductList .dx-toolbar-item,
  #sp_WH_ProductList_html #gridProductList .dx-toolbar-item-content {
    max-width: 100% !important;
    min-width: 0 !important;
    overflow: visible !important;
    white-space: normal !important;
  }

  /* 4. SỬA DỨT ĐIỂM LỖI 1: BỘ LỌC TỒN KHO (.stock-filter)
     - Chia 3 cột đều nhau hoặc 1 hàng Segmented Pill hoàn hảo
     - Tuyệt đối loại bỏ chia 2 cột làm nút Hết hàng bị rớt dòng lẻ loi */
  #sp_WH_ProductList_html .stock-filter {
    display: inline-grid !important;
    grid-template-columns: repeat(3, minmax(0, 1fr)) !important;
    align-items: center !important;
    gap: 4px !important;
    width: 100% !important;
    max-width: 360px !important;
    min-width: 260px !important;
    border-radius: 50px !important;
    border: 1px solid rgba(255, 255, 255, 0.15) !important;
    padding: 4px !important;
    background: rgba(255, 255, 255, 0.03) !important;
    box-sizing: border-box !important;
    flex: 0 0 auto !important;
  }

  #sp_WH_ProductList_html .stock-btn {
    border-radius: 40px !important;
    padding: 6px 14px !important;
    font-size: 0.85rem !important;
    border: none !important;
    background: transparent !important;
    cursor: pointer !important;
    transition: background-color 0.2s ease, color 0.2s ease !important;
    white-space: nowrap !important;
    font-weight: 600 !important;
    display: inline-flex !important;
    align-items: center !important;
    justify-content: center !important;
    text-align: center !important;
    width: 100% !important;
    overflow: hidden !important;
    text-overflow: ellipsis !important;
    box-sizing: border-box !important;
    color: #94a3b8 !important;
  }

  #sp_WH_ProductList_html .stock-btn.active {
    background: #198754 !important;
    color: #ffffff !important;
    box-shadow: 0 2px 6px rgba(25, 135, 84, 0.35) !important;
  }

  /* 5. SỬA DỨT ĐIỂM LỖI 2: CỤM TOOLBAR RIGHT & Ô TÌM KIẾM
     - Cho phép flex-wrap và co giãn chia sẻ không gian với nút bấm
     - Không cho ô tìm kiếm nuốt trọn 100% đẩy văng các nút Action */
  #sp_WH_ProductList_html .toolbar-right {
    display: flex !important;
    flex-wrap: wrap !important;
    align-items: center !important;
    justify-content: flex-end !important;
    gap: 8px !important;
    width: 100% !important;
    max-width: 100% !important;
  }

  /* Khóa cứng kích thước Searchbox 200px: KHÔNG TỰ Ý CO GIÃN LẤP ĐẦY DÒNG */
  #sp_WH_ProductList_html .ctlist-search-wrap {
    position: relative !important;
    display: inline-flex !important;
    align-items: center !important;
    flex: 0 0 200px !important;
    width: 200px !important;
    min-width: 180px !important;
    max-width: 220px !important;
    box-sizing: border-box !important;
    margin: 0 !important;
  }

  #sp_WH_ProductList_html .ctlist-search-icon {
    position: absolute !important;
    top: 50% !important;
    left: 10px !important;
    transform: translateY(-50%) !important;
    color: #94a3b8 !important;
    font-size: 0.85rem !important;
    pointer-events: none !important;
    z-index: 2 !important;
  }

  #sp_WH_ProductList_html .ctlist-search-input {
    height: 32px !important;
    padding: 0 10px 0 32px !important;
    border: 1px solid var(--bs-border-color, #475569) !important;
    border-radius: 6px !important;
    font-size: 0.875rem !important;
    width: 100% !important;
    min-width: 100% !important;
    max-width: 100% !important;
    background: var(--bs-body-bg, #1e293b) !important;
    color: var(--bs-body-color, #f8fafc) !important;
    box-sizing: border-box !important;
    outline: none !important;
    transition: border-color 0.15s !important;
  }

  #sp_WH_ProductList_html .ctlist-search-input:focus {
    border-color: #198754 !important;
  }

  /* 6. KHÓA NGUYÊN TỬ CÁC NÚT HÀNH ĐỘNG (Quy tắc 7: Atomic Non-shrink) */
  #sp_WH_ProductList_html .btn-ctlist-reload {
    height: 32px !important;
    width: 32px !important;
    min-width: 32px !important;
    max-width: 32px !important;
    display: inline-flex !important;
    align-items: center !important;
    justify-content: center !important;
    border: 1px solid var(--bs-border-color, #475569) !important;
    border-radius: 6px !important;
    background: var(--bs-body-bg, #1e293b) !important;
    color: #94a3b8 !important;
    cursor: pointer !important;
    padding: 0 !important;
    flex: 0 0 32px !important;
    flex-shrink: 0 !important;
    box-sizing: border-box !important;
  }

  #sp_WH_ProductList_html .btn-ctlist-reload:hover {
    color: #ffffff !important;
    border-color: #198754 !important;
  }

  /* TRIỆT TIÊU BẪY THẺ BỌC $btnGroup (Quy tắc 6.4 & 6.1):
     Phẳng hóa hoàn toàn để TỪNG BUTTON RỚT HÀNG ĐỘC LẬP khi thiếu chỗ, không rớt cả cụm! */
  #sp_WH_ProductList_html .toolbar-right > .d-flex {
    display: contents !important;
  }

  #sp_WH_ProductList_html .btn-add-productlist {
    white-space: nowrap !important;
    padding: 0 12px !important;
    height: 32px !important;
    font-weight: 500 !important;
    font-size: 0.85rem !important;
    border: none !important;
    border-radius: 6px !important;
    flex: 0 0 auto !important;
    flex-shrink: 0 !important;
    display: inline-flex !important;
    align-items: center !important;
    justify-content: center !important;
    gap: 5px !important;
    box-sizing: border-box !important;
  }

  #sp_WH_ProductList_html .dropdown {
    flex: 0 0 auto !important;
    flex-shrink: 0 !important;
  }

  #sp_WH_ProductList_html .dropdown .toolbar-toggle {
    height: 32px !important;
    width: 32px !important;
    display: inline-flex !important;
    align-items: center !important;
    justify-content: center !important;
    flex-shrink: 0 !important;
    border: 1px solid var(--bs-border-color, #475569) !important;
    border-radius: 6px !important;
    background: var(--bs-body-bg, #1e293b) !important;
    color: #94a3b8 !important;
    padding: 0 !important;
  }

  /* 7. RESPONSIVE MEDIA QUERIES (Windows Snap Layouts 1100px / 768px / 480px) */
  @media (max-width: 1100px) {
    #sp_WH_ProductList_html #gridProductList .dx-toolbar-before {
      width: 100% !important;
      flex: 1 1 100% !important;
    }

    #sp_WH_ProductList_html #gridProductList .dx-toolbar-after {
      width: 100% !important;
      flex: 1 1 100% !important;
      justify-content: flex-start !important;
      margin-left: 0 !important;
    }

    #sp_WH_ProductList_html .toolbar-right {
      justify-content: flex-start !important;
    }

    #sp_WH_ProductList_html .stock-filter {
      max-width: 100% !important;
      width: 100% !important;
    }
  }

  @media (max-width: 768px) {
    /* Searchbox vẫn giữ nguyên kích thước gọn gàng 200px, không chiếm hết dòng */
    #sp_WH_ProductList_html .ctlist-search-wrap {
      flex: 0 0 200px !important;
      width: 200px !important;
      max-width: 200px !important;
    }
  }

  @media (max-width: 480px) {
    #sp_WH_ProductList_html .stock-btn {
      padding: 6px 4px !important;
      font-size: 0.78rem !important;
    }

    #sp_WH_ProductList_html .btn-add-productlist {
      font-size: 0.8rem !important;
      padding: 0 8px !important;
    }

    #sp_WH_ProductList_html .modal-dialog {
      max-width: calc(100vw - 12px) !important;
      margin: 6px auto !important;
    }

    #sp_WH_ProductList_html .modal-body .col-6 {
      flex: 0 0 100% !important;
      max-width: 100% !important;
    }
  }

  /* 8. QUY TẮC 9: CÔ LẬP CUỘN BẢNG DỮ LIỆU LỚN (Wide-Component Scroll Isolation) */
  #sp_WH_ProductList_html #gridProductList .dx-datagrid-headers,
  #sp_WH_ProductList_html #gridProductList .dx-datagrid-rowsview,
  #sp_WH_ProductList_html #gridProductList .dx-datagrid-total-footer {
    overflow-x: auto !important;
    -webkit-overflow-scrolling: touch !important;
    width: 100% !important;
    max-width: 100% !important;
  }
</style>
